(()=>{
 const key='terra-position-v2', size=innerWidth<700?60:68, margin=12;
 const orb=document.createElement('button');orb.type='button';orb.className='terra-floating-orb';orb.setAttribute('aria-label','Abrir TERRA. Arrastra para mover; usa las flechas del teclado para ajustar su posición.');orb.setAttribute('aria-expanded','false');orb.title='Abrir TERRA · Arrastra para mover';
 orb.innerHTML=`<svg viewBox="0 0 100 100" aria-hidden="true"><defs><radialGradient id="terraSphere" cx="32%" cy="24%" r="76%"><stop stop-color="#edffe3"/><stop offset=".16" stop-color="#b0d8ae"/><stop offset=".43" stop-color="#43846a"/><stop offset=".75" stop-color="#173f32"/><stop offset="1" stop-color="#071d1b"/></radialGradient><linearGradient id="terraLine" x2="1" y2="1"><stop stop-color="#e8e2a0"/><stop offset="1" stop-color="#6bcba6"/></linearGradient><clipPath id="terraClip"><circle cx="50" cy="50" r="46"/></clipPath></defs><circle cx="50" cy="50" r="47" fill="url(#terraSphere)" stroke="#c3dfb3" stroke-width="1.5"/><g class="terra-filaments" clip-path="url(#terraClip)" fill="none" stroke="url(#terraLine)" stroke-width=".9" opacity=".85"><path d="M14 63 C30 20 51 19 71 37 S89 68 67 78 S29 84 20 60 M17 38 Q42 67 82 48 M27 80 Q43 51 74 21 M22 68 Q42 66 50 48 Q58 30 76 34"/><circle cx="50" cy="50" r="34" opacity=".35"/></g><g class="terra-sparks" fill="#f3df99"><circle cx="22" cy="68" r="1.8"/><circle cx="50" cy="48" r="2"/><circle cx="76" cy="34" r="1.8"/><circle cx="82" cy="48" r="1.5"/></g><path d="M45 60 Q30 58 32 45 Q44 46 48 58 M59 42 Q60 28 72 29 Q71 40 59 42" fill="#b4dfa5" opacity=".76"/><ellipse cx="34" cy="24" rx="21" ry="9" fill="#fff" opacity=".20" transform="rotate(-32 34 24)"/><circle cx="50" cy="50" r="45" fill="none" stroke="#fff" opacity=".16"/></svg>`;
 const style=document.createElement('style');style.textContent=`.terra-floating-orb{position:fixed;z-index:2147483000;width:${size}px;height:${size}px;padding:0;border:0;border-radius:50%;background:transparent;cursor:grab;touch-action:none;filter:drop-shadow(0 5px 9px #0009);transition:filter .2s,transform .2s;animation:terra-breathe 5s ease-in-out infinite}.terra-floating-orb svg{display:block;width:100%;height:100%}.terra-floating-orb:hover{filter:drop-shadow(0 6px 12px #000b) brightness(1.15);transform:scale(1.06)}.terra-floating-orb:active{cursor:grabbing}.terra-floating-orb:focus-visible{outline:3px solid #e3b74d;outline-offset:4px}.terra-filaments{transform-origin:50px 50px;animation:terra-flow 16s ease-in-out infinite alternate}.terra-sparks{animation:terra-glimmer 4s ease-in-out infinite alternate}@keyframes terra-flow{to{transform:rotate(14deg) scale(1.06)}}@keyframes terra-glimmer{to{opacity:.4}}@keyframes terra-breathe{50%{filter:drop-shadow(0 5px 13px #c0dfa088) brightness(1.08)}}@media(prefers-reduced-motion:reduce){.terra-floating-orb,.terra-filaments,.terra-sparks{animation:none;transition:none}}`;document.head.append(style);document.body.append(orb);
 const frame=document.createElement('iframe');frame.title='Asistente TERRA';frame.src='/terra/';frame.hidden=true;frame.style.cssText='position:fixed;border:0;background:transparent;z-index:2147482999;';document.body.append(frame);
 let x=innerWidth-size-18,y=innerHeight-size-18,drag=null,moved=false,opened=false,panelHeight=520;
 const clamp=()=>{x=Math.max(margin,Math.min(x,Math.max(margin,innerWidth-size-margin)));y=Math.max(margin,Math.min(y,Math.max(margin,innerHeight-size-margin)))};
 function place(){clamp();orb.style.left=x+'px';orb.style.top=y+'px';if(opened){const w=Math.min(370,innerWidth-16),h=Math.min(panelHeight,innerHeight-16);frame.style.width=w+'px';frame.style.height=h+'px';frame.style.left=Math.max(8,Math.min(innerWidth-w-8,x+size-w))+'px';let top=y-h-8;if(top<8)top=y+size+8;if(top+h>innerHeight-8)top=Math.max(8,innerHeight-h-8);frame.style.top=top+'px'}}
 try{const p=JSON.parse(localStorage.getItem(key));if(p&&Number.isFinite(p.x)&&Number.isFinite(p.y)){x=p.x*Math.max(0,innerWidth-size);y=p.y*Math.max(0,innerHeight-size)}}catch{}
 function save(){try{localStorage.setItem(key,JSON.stringify({x:x/Math.max(1,innerWidth-size),y:y/Math.max(1,innerHeight-size)}))}catch{}}
 orb.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={px:e.clientX,py:e.clientY,x,y};moved=false;orb.setPointerCapture(e.pointerId)});
 orb.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.px,dy=e.clientY-drag.py;if(Math.hypot(dx,dy)>5)moved=true;if(moved){x=drag.x+dx;y=drag.y+dy;place()}});
 orb.addEventListener('pointerup',()=>{if(drag&&moved)save();drag=null});orb.addEventListener('pointercancel',()=>{drag=null});
 orb.addEventListener('click',()=>{if(moved){moved=false;return}if(opened){frame.hidden=true;opened=false;orb.setAttribute('aria-expanded','false');return}opened=true;frame.hidden=false;place();orb.setAttribute('aria-expanded','true');frame.contentWindow.postMessage({terraOpen:true},location.origin)});
 orb.addEventListener('keydown',e=>{const d= e.shiftKey?30:10;if(e.key==='ArrowLeft')x-=d;else if(e.key==='ArrowRight')x+=d;else if(e.key==='ArrowUp')y-=d;else if(e.key==='ArrowDown')y+=d;else return;e.preventDefault();place();save()});
 window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==frame.contentWindow)return;if(Number.isFinite(e.data?.terraHeight))return;if(typeof e.data?.terraPanel!=='boolean')return;if(!e.data.terraPanel){opened=false;frame.hidden=true;orb.setAttribute('aria-expanded','false');orb.focus()}});window.addEventListener('keydown',e=>{if(e.key==='Escape'&&opened){opened=false;frame.hidden=true;orb.setAttribute('aria-expanded','false');orb.focus()}});window.addEventListener('resize',()=>{if(!localStorage.getItem(key)){x=innerWidth-size-18;y=innerHeight-size-18}place()});place();if('serviceWorker'in navigator){navigator.serviceWorker.register('/sw.js').catch(()=>{})}
})();
